"""生成测试和评测用的虚构招标文件：tender-fictional.docx，再用 LibreOffice 转成 tender-fictional.pdf。

两份文件都已提交进仓库，平时不需要重新生成。改了下面的内容后：
    python tests/fixtures/make_tender.py
    soffice --headless --convert-to pdf --outdir tests/fixtures tests/fixtures/tender-fictional.docx

全部内容虚构：采购人、项目、金额、日期、联系方式都不对应任何真实机构。
故意放进了旧版研究 Agent 犯过错的几种写法，评测时用得上：
    - "合同签订后60日内完成系统开发"（工期）和"驻场不少于30个工作日"（驻场）是两条不同的要求
    - 预算金额和最高限价同为 48 万元，但它们是两种不同的钱
    - "2026年10月8日至13日"是日期范围，不是 13 天
    - "关联供应商不得共同参加同一合同项下的采购活动"不等于"不能有控股关系"
    - 第六章是投标文件格式（模板），不是要求
"""

from pathlib import Path

from docx import Document

HERE = Path(__file__).parent

CHAPTERS = [
    (
        "第一章 投标邀请",
        [
            ("p", "虚构市数据资源局（以下简称采购人）就智能知识库平台建设项目进行公开招标，欢迎合格的供应商参加投标。"),
            ("h2", "一、项目基本情况"),
            ("p", "项目编号：XG-2026-0815"),
            ("p", "项目名称：虚构市智能知识库平台建设项目"),
            ("p", "预算金额：48万元"),
            ("p", "最高限价：48万元"),
            ("p", "采购需求：建设面向全市政务人员的智能知识库平台，提供文档检索、智能问答和知识运营功能。"),
            ("h2", "二、获取招标文件"),
            ("p", "时间：2026年10月8日至13日，每天上午9:00至11:30，下午14:00至17:00（北京时间，法定节假日除外）。"),
            ("p", "方式：登录虚构市公共资源交易平台，使用CA数字证书在线获取。招标文件售价：0元。"),
            ("h2", "三、提交投标文件截止时间、开标时间和地点"),
            ("p", "提交投标文件截止时间：2026年10月29日09:30（北京时间）。"),
            ("p", "联系人：张工，电话：0000-12345678，邮箱：contact@example.invalid"),
        ],
    ),
    (
        "第二章 投标人须知",
        [
            ("h2", "一、投标人资格要求"),
            ("p", "（一）满足《中华人民共和国政府采购法》第二十二条规定，具有独立承担民事责任的能力。"),
            ("p", "（二）参加政府采购活动前三年内，在经营活动中没有重大违法记录。"),
            (
                "p",
                "（三）单位负责人为同一人或者存在直接控股、管理关系的不同供应商，不得参加同一合同项下的政府采购活动。",
            ),
            ("p", "（四）本项目不接受联合体投标。"),
            ("h2", "二、投标保证金"),
            ("p", "本项目不收取投标保证金。"),
        ],
    ),
    (
        "第三章 采购需求",
        [
            ("h2", "一、技术要求"),
            ("p", "1. 平台应支持PDF、Word、Excel等常见格式文档的批量导入和自动解析，单批次导入不少于500份文档。"),
            ("p", "2. 平台应提供基于大语言模型的智能问答功能，回答须标注引用的原文出处。"),
            ("p", "3. 平台应支持私有化部署，所有数据存储在采购人指定的政务云环境内，不得传输至境外。"),
            ("p", "4. 平台应提供知识运营后台，支持按部门设置文档访问权限。"),
            ("h2", "二、交付要求"),
            ("p", "1. 合同签订后60日内完成系统开发、部署和试运行。"),
            (
                "p",
                "2. 项目实施期间，中标人须安排不少于2名工程师驻场服务，驻场时间不少于30个工作日，服务地点为虚构市政务服务中心。",
            ),
            ("p", "3. 质保期为验收合格之日起12个月，质保期内提供7×24小时远程技术支持。"),
            ("h2", "三、人员要求"),
            ("p", "项目经理须具有信息系统项目管理师（高级）证书，并提供近6个月社保缴纳证明。"),
        ],
    ),
    (
        "第四章 合同主要条款",
        [
            ("p", "1. 付款方式：合同签订后支付合同金额的30%，项目终验合格后支付60%，质保期满后支付10%。"),
            ("p", "2. 履约保证金：合同金额的5%，验收合格后无息退还。"),
        ],
    ),
    (
        "第五章 评标方法和评分标准",
        [
            ("p", "本项目采用综合评分法，满分100分。"),
            (
                "table",
                [
                    ["评分项", "分值", "评分标准"],
                    ["价格", "30", "满足招标文件要求且投标价格最低的报价为评标基准价，其价格分为满分"],
                    ["技术方案", "40", "根据技术方案的完整性、可行性和针对性综合评分"],
                    ["类似业绩", "15", "近三年每提供1个知识库或智能问答类项目合同得5分，最多15分"],
                    ["售后服务", "15", "根据售后服务方案和响应时间综合评分"],
                ],
            ),
        ],
    ),
    (
        "第六章 投标文件格式",
        [
            ("p", "附件1：投标函（格式）"),
            (
                "p",
                "致：（采购人名称）我方愿意按照招标文件的一切要求，提供本项目的全部服务，投标总价为人民币（大写）______元。",
            ),
            ("p", "附件2：资格承诺函（格式）"),
            ("p", "我单位承诺：参加本次政府采购活动前三年内，在经营活动中没有重大违法记录。"),
        ],
    ),
]


def build() -> Path:
    document = Document()
    document.add_heading("虚构市智能知识库平台建设项目 招标文件", level=0)
    for title, items in CHAPTERS:
        document.add_heading(title, level=1)
        for kind, value in items:
            if kind == "h2":
                document.add_heading(value, level=2)
            elif kind == "p":
                document.add_paragraph(value)
            else:
                table = document.add_table(rows=len(value), cols=len(value[0]))
                table.style = "Table Grid"  # 带边框，PDF 里才能被识别成表格
                for r, row in enumerate(value):
                    for c, cell in enumerate(row):
                        table.cell(r, c).text = cell
    path = HERE / "tender-fictional.docx"
    document.save(path)
    return path


if __name__ == "__main__":
    print(build())
